<?php
require_once __DIR__.'/config.php'; require_once __DIR__.'/functions.php'; require_login();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id||$id<1){http_response_code(400);exit('Invalid post ID.');}
$st=$pdo->prepare('SELECT * FROM posts WHERE id=:id LIMIT 1');$st->execute([':id'=>$id]);$post=$st->fetch();if(!$post){http_response_code(404);exit('Post not found.');}if(!can_manage_post($pdo,(int)$post['user_id'])){http_response_code(403);exit('You do not have permission to manage this post.');}
$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); if(isset($_POST['delete'])){$del=$pdo->prepare('DELETE FROM posts WHERE id=:id');$del->execute([':id'=>$id]);if($post['featured_image']){@unlink(__DIR__.'/uploads/'.$post['featured_image']);}redirect('dashboard.php?deleted=1');}
 $title=trim((string)($_POST['title']??''));$content=trim((string)($_POST['content']??''));$category=trim((string)($_POST['category']??'General'));$tags=trim((string)($_POST['tags']??''));$status=(string)($_POST['status']??'draft');$errors=validate_post_input($title,$content,$category,$tags);if(!in_array($status,['draft','published'],true))$errors[]='Invalid post status.';
 $newImage=null;if(!$errors){[$newImage,$imageError]=upload_featured_image($_FILES['featured_image']??[],$post['featured_image']);if($imageError)$errors[]=$imageError;}
 if(!$errors){$image=$newImage??$post['featured_image'];$up=$pdo->prepare('UPDATE posts SET title=:title,content=:content,category=:category,tags=:tags,status=:status,featured_image=:image WHERE id=:id');$up->execute([':title'=>$title,':content'=>$content,':category'=>$category,':tags'=>$tags,':status'=>$status,':image'=>$image,':id'=>$id]);redirect('dashboard.php?updated=1');}
 $post=array_merge($post,['title'=>$title,'content'=>$content,'category'=>$category,'tags'=>$tags,'status'=>$status]);
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit post | Blog Studio</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">B</span> Blog Studio</a><nav><a href="dashboard.php">Dashboard</a><a href="index.php">View blog</a></nav></header><main class="container narrow editor-page"><a href="dashboard.php">← Dashboard</a><p class="eyebrow">CONTENT STUDIO</p><h1>Edit story</h1><?php foreach($errors as $error):?><p class="error"><?=e($error)?></p><?php endforeach;?>
<form class="editor-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label for="title">Post title</label><input id="title" name="title" maxlength="200" required value="<?=e($post['title'])?>"><label for="content">Article content</label><textarea id="content" name="content" rows="14" maxlength="50000" required><?=e($post['content'])?></textarea><div class="form-grid"><div><label for="category">Category</label><select id="category" name="category"><?php foreach(['General','Technology','Lifestyle','Education','Business','Travel','Health','News'] as $cat):?><option <?= $post['category']===$cat?'selected':''?>><?=e($cat)?></option><?php endforeach;?></select></div><div><label for="tags">Tags <span class="muted">(comma separated)</span></label><input id="tags" name="tags" maxlength="500" value="<?=e($post['tags'])?>"></div></div><?php if($post['featured_image']):?><p class="muted">Current image</p><img class="upload-preview" src="uploads/<?=e($post['featured_image'])?>" alt="Current featured image"><?php endif;?><label for="featured_image">Replace featured image</label><input id="featured_image" type="file" name="featured_image" accept="image/jpeg,image/png,image/webp"><div class="form-actions"><label class="status-select">Status <select name="status"><option value="draft" <?=$post['status']==='draft'?'selected':''?>>Draft</option><option value="published" <?=$post['status']==='published'?'selected':''?>>Published</option></select></label><button type="submit">Update post →</button></div></form><form method="post" class="delete-form" onsubmit="return confirm('Delete this post permanently?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="danger" name="delete" value="1">Delete post</button></form></main></body></html>
